package com.northstar.crm.ui;

import com.northstar.crm.domain.*;import com.northstar.crm.security.ActorResolver;import com.northstar.crm.service.*;import com.vaadin.flow.component.*;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.data.renderer.ComponentRenderer;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;import java.math.BigDecimal;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Route(value="",layout=MainLayout.class) @PageTitle("Overview · Northstar") @PermitAll public class DashboardView extends VerticalLayout {
 public DashboardView(ActorResolver actors,OrganizationService organizations,DealService deals,EscalationService escalations){var actor=actors.current();var orgs=organizations.search("");var queue=escalations.queue();var risk=orgs.stream().filter(o->o.getHealth()==Health.WATCH||o.getHealth()==Health.CRITICAL).count();BigDecimal pipeline=BigDecimal.ZERO;if(actor.getRole()!=Role.CUSTOMER_CONTACT){for(var org:orgs)for(var d:deals.forOrganization(org.getId()))if(!Set.of(DealStage.CLOSED_LOST,DealStage.CLOSED_WON).contains(d.getStage()))pipeline=pipeline.add(d.getValue().multiply(BigDecimal.valueOf(d.getProbability())).movePointLeft(2));}var open=queue.stream().filter(e->e.getStatus()!=EscalationStatus.CLOSED&&e.getStatus()!=EscalationStatus.RESOLVED).count();var metrics=new Div(UiKit.metric(actor.getRole()==Role.CUSTOMER_CONTACT?"Your organization":"Accounts in scope",String.valueOf(orgs.size()),actor.getRole()==Role.PLATFORM_ADMIN?"Across the platform":"Authorized workspace","metric-blue"),UiKit.metric("Renewal attention",String.valueOf(risk),"Watch or critical health","metric-amber"),UiKit.metric("Open escalations",String.valueOf(open),"Assigned or customer-visible","metric-red"),UiKit.metric("Weighted pipeline",actor.getRole()==Role.CUSTOMER_CONTACT?"Private":"£"+pipeline.setScale(0,java.math.RoundingMode.HALF_UP),"Server-calculated probability","metric-mint"));metrics.addClassName("metric-grid");var riskRail=new Div(new Span("RENEWAL RADAR"),new H2(nextRenewal(orgs)),new Paragraph("The closest renewal in your authorized portfolio."));riskRail.addClassName("risk-rail");var grid=new Grid<Escalation>();grid.addColumn(Escalation::getSubject).setHeader("Escalation").setFlexGrow(2);grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getSeverity()))).setHeader("Severity");grid.addColumn(new ComponentRenderer<>(e->UiKit.badge(e.getStatus()))).setHeader("Status");grid.addColumn(e->ChronoUnit.HOURS.between(e.getCreatedAt(),Instant.now())+"h").setHeader("Age");grid.setItems(queue.stream().limit(7).toList());grid.addItemClickListener(e->UI.getCurrent().navigate("escalations/"+e.getItem().getId()));grid.setAllRowsVisible(true);var work=new VerticalLayout(new H2(actor.getRole()==Role.CUSTOMER_CONTACT?"Your open requests":"Work requiring attention"),grid);work.addClassName("panel");add(UiKit.page("TODAY / "+LocalDate.now(),greeting(actor.getDisplayName()),dashboardCopy(actor.getRole()),metrics,riskRail,work));setSizeFull();setPadding(false);}
 private String greeting(String name){return "Good "+(LocalTime.now().getHour()<12?"morning":"afternoon")+", "+name.split(" ")[0];}private String dashboardCopy(Role role){return switch(role){case PLATFORM_ADMIN->"Platform health, access changes and customer risk in one view.";case ACCOUNT_MANAGER->"Your renewals, pipeline and customer commitments, ordered by urgency.";case SUPPORT_AGENT->"Assigned escalations and customer context for a focused handover.";case CUSTOMER_CONTACT->"Shared documents and requests for your organization.";};}private String nextRenewal(List<Organization> orgs){return orgs.stream().min(Comparator.comparing(Organization::getRenewalDate)).map(o->o.getName()+" · "+o.getRenewalDate()).orElse("No renewal dates in scope");}
}
